/**
 * The icon set for the studio (home/folder) surfaces, transcribed path-for-path from the
 * supplied reference design export so the rendered glyphs match it exactly rather than
 * approximating it with a lookalike pack. Every icon is a single-colour vector; the tint
 * comes from the call site, which is what the reference does per appearance.
 */
object StudioIcons {

    /**
     * Build one icon from reference path data. The reference viewBoxes carry an origin
     * offset (their coordinates are absolute within the source artboard), so the group is
     * translated back to 0,0 and the viewport is the viewBox size.
     */
    private fun studioIcon(
        minX: Float,
        minY: Float,
        width: Float,
        height: Float,
        vararg pathData: String,
        rules: Array<String> = emptyArray(),
    ): ImageVector {
        val builder = ImageVector.Builder(
            name = "studio",
            defaultWidth = width.dp,
            defaultHeight = height.dp,
            viewportWidth = width,
            viewportHeight = height,
        )
        builder.addGroup(name = "g", translationX = -minX, translationY = -minY)
        pathData.forEachIndexed { i, d ->
            builder.addPath(
                pathData = PathParser().parsePathString(d).toNodes(),
                fill = SolidColor(Color.White),
                pathFillType = if (rules.getOrNull(i) == "evenodd") PathFillType.EvenOdd else PathFillType.NonZero,
            )
        }
        return builder.build()
    }

